import math
rails={-1:[],1:[]}
def estimate(points,x):
    q=sorted(points,key=lambda p:abs(p[0]-x))[:6]
    if len(q)<2:return None
    mx=sum(p[0] for p in q)/len(q); my=sum(p[1] for p in q)/len(q)
    den=sum((p[0]-mx)**2 for p in q)
    slope=sum((p[0]-mx)*(p[1]-my) for p in q)/max(.1,den)
    return my+max(-1,min(1,slope))*(x-mx)
def control(o):
    dt=o['dt']; v=o['motion']['v_mps']; a=math.radians(o['steer_deg']); yaw=v*math.tan(a)*dt/2.5
    c=math.cos(yaw); s=math.sin(yaw)
    for side in rails:
        rails[side]=[(c*(x-v*dt)+s*y,-s*(x-v*dt)+c*y) for x,y in rails[side]]
    for side,name in [(1,'left_mirror'),(-1,'right_mirror')]:
        view=o['views'].get(name)
        if view:
            ox,oy=view['origin']; pts=[]
            for b,d in view['walls']:
                b=math.radians(b); x=ox+d*math.cos(b); y=oy+d*math.sin(b)
                if -18<x<-2 and side*y>.8:pts.append((x,y))
            if len(pts)>3:rails[side]=pts
    rx,ry=o['rig']['trailer_rear']; look=3.5; x=rx-look
    left=estimate(rails[1],x); right=estimate(rails[-1],x)
    desired=0
    if left is not None and right is not None:
        mid=(left+right)/2
        desired=math.degrees(math.atan2(mid-ry,look))
    elif left is not None:desired=math.degrees(math.atan2(left-2.6-ry,look))
    elif right is not None:desired=math.degrees(math.atan2(right+2.6-ry,look))
    desired=max(-24,min(24,desired))
    h=o['hitch_deg']; steer=max(-38,min(38,2.1*h-1.6*desired))
    speed=-.65 if left is not None and right is not None else -.45
    gaze=64 if int(o['t']/3)%2==0 else -64
    return steer,speed,gaze

