phase=0
dist=0.0
elapsed=0.0
def control(o):
    global phase,dist,elapsed
    if o['hitch_deg']<27:
        wake('Hitch reduced; reassess clearance')
        return (0,0,160)
    steering=-45 if phase%2==0 else 45
    speed=0.04 if phase%2==0 else -0.04
    dist+=abs(o['motion']['v_mps'])*o['dt']
    ready=abs(o['steer_deg']-steering)<2 and o['motion']['hold_s']<=0
    if ready:elapsed+=o['dt']
    if dist>=0.012 or elapsed>=0.7:
        phase+=1
        dist=0.0
        elapsed=0.0
        steering=-45 if phase%2==0 else 45
        return (steering,0,160)
    return (steering,speed if ready else 0,160)

